from __future__ import annotations
import numpy as np

# ── ADAPTED GAME-SPECIFIC PRIORS ──────────────────────────────────────────
# Increased movable size to capture larger blocks/pieces.
_SKEL_MOVABLE_MAX_SIZE = 25 
_SKEL_SEARCH_DEPTH = 8
_SKEL_BRANCH = 4
_SKEL_NEAR = 8.0

def _skel_background(frame: np.ndarray) -> int:
    f = np.asarray(frame)
    if f.size == 0:
        return 0
    vals, counts = np.unique(f, return_counts=True)
    return int(vals[int(counts.argmax())])

def _skel_flood_regions(frame: np.ndarray, bg: int) -> list:
    f = np.asarray(frame)
    h, w = f.shape
    seen = [[False] * w for _ in range(h)]
    regions = []
    for y in range(h):
        for x in range(w):
            if seen[y][x]:
                continue
            seen[y][x] = True
            color = int(f[y, x])
            if color == bg:
                continue
            cells = [(y, x)]
            stack = [(y, x)]
            while stack:
                cy, cx = stack.pop()
                for ny, nx in ((cy - 1, cx), (cy + 1, cx), (cy, cx - 1), (cy, cx + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] \
                            and int(f[ny, nx]) == color:
                        seen[ny][nx] = True
                        cells.append((ny, nx))
                        stack.append((ny, nx))
            mx = sum(c[1] for c in cells) / len(cells)
            my = sum(c[0] for c in cells) / len(cells)
            regions.append({
                "color": color, "cells": cells, "size": len(cells),
                "cx": int(round(mx)), "cy": int(round(my)),
            })
    return regions

def _skel_classify(regions, trace=None):
    movable = [r for r in regions if r["size"] <= _SKEL_MOVABLE_MAX_SIZE]
    fixed = [r for r in regions if r["size"] > _SKEL_MOVABLE_MAX_SIZE]
    if trace is not None:
        trace.append(f"parse regions={len(regions)} movable={len(movable)} fixed={len(fixed)}")
    return movable, fixed

def _skel_learn_move(transitions, bg, trace=None):
    to_loc = 0
    click_piece = 0
    for t in transitions:
        xy = t.get("xy")
        if xy is None: continue
        before = np.asarray(t["before"])
        after = np.asarray(t["after"])
        if before.shape != after.shape: continue

        diff = np.where(before != after)
        if len(diff[0]) == 0: continue

        # Check if the click was on a piece that then moved
        before_color = before[int(xy[1]), int(xy[0])]
        if before_color != bg:
            click_piece += 1

        # Check if the piece moved toward the click
        d = abs(float(diff[1].mean()) - xy[0]) + abs(float(diff[0].mean()) - xy[1])
        if d <= _SKEL_NEAR:
            to_loc += 1

    mode = "to_location" if to_loc > click_piece else ("click_piece" if click_piece > 0 else "none")
    if trace is not None:
        trace.append(f"move-model to_loc={to_loc} click_piece={click_piece} -> {mode}")
    return mode

def _skel_plan_to_location(movers, targets, trace=None):
    tgt = [(t["cx"], t["cy"]) for t in targets]
    best = {"key": None, "assign": []}
    limit = min(len(movers), _SKEL_SEARCH_DEPTH)

    def leaf(cost, assign):
        key = (-len(assign), cost)
        if best["key"] is None or key < best["key"]:
            best["key"] = key
            best["assign"] = list(assign)

    def dfs(i, used, cost, assign):
        if i >= limit:
            leaf(cost, assign)
            return
        mx, my = movers[i]["cx"], movers[i]["cy"]
        order = sorted(range(len(tgt)), key=lambda j: abs(tgt[j][0] - mx) + abs(tgt[j][1] - my))
        placed = False
        for j in order[:_SKEL_BRANCH]:
            if j in used: continue
            placed = True
            used.add(j)
            assign.append(tgt[j])
            dfs(i + 1, used, cost + abs(tgt[j][0] - mx) + abs(tgt[j][1] - my), assign)
            assign.pop()
            used.discard(j)
        if not placed:
            dfs(i + 1, used, cost, assign)

    dfs(0, set(), 0.0, [])
    return best["assign"]

def simdfs_skel_core(current_frame, transitions, act, trace=None):
    frame = np.asarray(current_frame)
    bg = _skel_background(frame)
    regions = _skel_flood_regions(frame, bg)
    movers, fixed = _skel_classify(regions, trace)
    mode = _skel_learn_move(transitions, bg, trace)

    if mode == "to_location" and movers and fixed:
        plan = _skel_plan_to_location(movers, fixed, trace)
        for (x, y) in plan:
            act("CLICK", int(x), int(y))
        if plan: return

    if mode == "click_piece" and movers:
        clicked = {(int(t["xy"][0]), int(t["xy"][1])) for t in transitions if t.get("xy")}
        for r in movers:
            if (r["cx"], r["cy"]) not in clicked:
                act("CLICK", int(r["cx"]), int(r["cy"]))
                return
        act("CLICK", int(movers[0]["cx"]), int(movers[0]["cy"]))
        return

    clicked = {(int(t["xy"][0]), int(t["xy"][1])) for t in transitions if t.get("xy")}
    for r in movers:
        if (r["cx"], r["cy"]) not in clicked:
            if trace is not None: trace.append(f"probe piece ({r['cx']},{r['cy']})")
            act("CLICK", int(r["cx"]), int(r["cy"]))
            return

    if fixed:
        for r in fixed:
            if (r["cx"], r["cy"]) not in clicked:
                act("CLICK", int(r["cx"]), int(r["cy"]))
                return

from __future__ import annotations
import numpy as np

# ── SANDBOX CONTRACT ──────────────────────────────────────────────────────────

_MAX_STENCIL = 12
_MIN_STENCILS = 4

def color_histogram(frame: np.ndarray, ncolors: int = 16) -> np.ndarray:
    flat = np.asarray(frame).ravel()
    return np.bincount(flat[(flat >= 0) & (flat < ncolors)], minlength=ncolors)

def _binarize(frame: np.ndarray) -> tuple[np.ndarray, int, int]:
    hist = color_histogram(frame)
    off = int(hist.argmax()) if hist.any() else 0
    on_candidates = [c for c in range(len(hist)) if hist[c] > 0 and c != off]
    on = on_candidates[0] if on_candidates else off
    bits = (frame != off).astype(np.uint8)
    return bits, off, on

def _gf2_solve(a: np.ndarray, b: np.ndarray) -> np.ndarray | None:
    m = np.concatenate([a.copy() % 2, (b.copy() % 2).reshape(-1, 1)], axis=1).astype(np.uint8)
    rows, cols = m.shape
    nvars = cols - 1
    pivot_col_of_row: list[int] = []
    r = 0
    for c in range(nvars):
        piv = None
        for rr in range(r, rows):
            if m[rr, c]:
                piv = rr
                break
        if piv is None:
            continue
        m[[r, piv]] = m[[piv, r]]
        for rr in range(rows):
            if rr != r and m[rr, c]:
                m[rr] ^= m[r]
        pivot_col_of_row.append(c)
        r += 1
        if r == rows:
            break
    for rr in range(rows):
        if not m[rr, :nvars].any() and m[rr, nvars]:
            return None
    x = np.zeros(nvars, dtype=np.uint8)
    for i, c in enumerate(pivot_col_of_row):
        x[c] = m[i, nvars]
    return x

def _diff_cells(before: Any, after: Any) -> list[tuple[int, int]]:
    a = np.asarray(before)
    b = np.asarray(after)
    if a.shape != b.shape:
        return []
    ys, xs = np.where(a != b)
    return [(int(y), int(x)) for y, x in zip(ys, xs)]

def _stencils_from_transitions(
    transitions: list[dict[str, Any]],
) -> dict[tuple[int, int], set[tuple[int, int]]]:
    stencils: dict[tuple[int, int], set[tuple[int, int]]] = {}
    for t in transitions:
        xy = t.get("xy")
        if xy is None:
            continue
        cells = _diff_cells(t["before"], t["after"])
        if 1 <= len(cells) <= _MAX_STENCIL:
            stencils[(int(xy[0]), int(xy[1]))] = set(cells)
    return stencils

def _component_centroids(frame: np.ndarray) -> list[tuple[int, int]]:
    f = np.asarray(frame)
    h, w = f.shape
    hist = color_histogram(f)
    bg = int(hist.argmax()) if hist.any() else -1
    seen = [[False] * w for _ in range(h)]
    out: list[tuple[int, int]] = []
    for y in range(h):
        for x in range(w):
            if seen[y][x]:
                continue
            seen[y][x] = True
            color = int(f[y, x])
            if color == bg:
                continue
            cells = [(y, x)]
            stack = [(y, x)]
            while stack:
                cy, cx = stack.pop()
                for ny, nx in ((cy - 1, cx), (cy + 1, cx), (cy, cx - 1), (cy, cx + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] \
                            and int(f[ny, nx]) == color:
                        seen[ny][nx] = True
                        cells.append((ny, nx))
                        stack.append((ny, nx))
            cy = sum(c[0] for c in cells) / len(cells)
            cx = sum(c[1] for c in cells) / len(cells)
            out.append((int(round(cx)), int(round(cy))))
    return out

def _next_probe(
    frame: np.ndarray, clicked: set[tuple[int, int]],
) -> tuple[int, int] | None:
    f = np.asarray(frame)
    h, w = f.shape
    candidates: list[tuple[int, int]] = list(_component_centroids(f))
    step = max(1, min(h, w) // 8)
    for y in range(step // 2, h, step):
        for x in range(step // 2, w, step):
            candidates.append((x, y))
    for x, y in candidates:
        if (x, y) not in clicked:
            return (x, y)
    return None

def _solve_board(
    frame: np.ndarray,
    stencils: dict[tuple[int, int], set[tuple[int, int]]],
    trace: list[str] | None = None,
) -> list[tuple[int, int]] | None:
    bits, _off, _on = _binarize(np.asarray(frame))
    h, w = bits.shape
    clicks = sorted(stencils)
    n_cells = h * w
    a = np.zeros((n_cells, len(clicks)), dtype=np.uint8)
    for j, click in enumerate(clicks):
        for (r, c) in stencils[click]:
            if 0 <= r < h and 0 <= c < w:
                a[r * w + c, j] = 1
    best: list[tuple[int, int]] | None = None
    for target in (0, 1):
        b = ((bits.reshape(-1) ^ target) % 2).astype(np.uint8)
        x = _gf2_solve(a, b)
        if x is None:
            continue
        plan = [(int(clicks[j][0]), int(clicks[j][1]))
                for j in range(len(clicks)) if x[j]]
        if plan and (best is None or len(plan) < len(best)):
            best = plan
    return best

def toggle_core(
    current_frame: Any,
    transitions: list[dict[str, Any]],
    act: Callable[..., None],
    trace: list[str] | None = None,
) -> None:
    frame = np.asarray(current_frame)
    stencils = _stencils_from_transitions(transitions)

    # CRITICAL FIX: Track ALL attempted clicks, not just those that produced stencils.
    # This prevents the solver from getting stuck on "dead" pixels.
    all_attempted = set()
    for t in transitions:
        xy = t.get("xy")
        if xy:
            all_attempted.add((int(xy[0]), int(xy[1])))

    if len(stencils) >= _MIN_STENCILS:
        plan = _solve_board(frame, stencils, trace)
        if plan:
            if trace is not None:
                trace.append(f"plan={len(plan)} clicks")
            for (x, y) in plan:
                act("CLICK", x, y)
            return

    probe = _next_probe(frame, all_attempted)
    if probe is not None:
        if trace is not None:
            trace.append(
                f"stencils={len(stencils)} (<{_MIN_STENCILS}) -> "
                f"probe ({probe[0]},{probe[1]})"
            )
        act("CLICK", probe[0], probe[1])
